  const grams: string[] = [];
  for (const run of text.match(CJK_RUN_RE) ?? []) {
    for (let i = 0; i + 2 <= run.length; i += 1) {
      grams.push(run.slice(i, i + 2));
    }
  }
  return grams;
}

